def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = prev.get('bid', 0.0)
                prev_bids.append(b)
                if b >= 80:
                    dangerous_prev.append(b)

    if not alive:
        return float(min(budget, 18.0))

    competitors = len(alive) + 1
    scarcity = competitors * WATER_REQ - supply

    high_pressure = max(prev_bids) if prev_bids else 0.0
    moderate_pressure = 0.0
    if prev_bids:
        sorted_bids = sorted(prev_bids)
        moderate_pressure = sorted_bids[int(len(sorted_bids) // 2)]

    urgent = hp <= 3 or no_water >= 2
    stressed = hp <= 5 or no_water >= 1

    if urgent:
        if scarcity >= 25:
            bid = max(105.0, high_pressure + 3.0)
        elif scarcity >= 15:
            bid = max(88.0, moderate_pressure + 2.0)
        else:
            bid = 72.0
        return float(min(budget, bid))

    if scarcity <= 0:
        if high_pressure >= 110 and hp >= 6:
            bid = 8.0
        elif high_pressure >= 85:
            bid = 14.0
        else:
            bid = 18.0
        return float(min(budget, bid))

    if scarcity <= 13:
        if stressed:
            bid = max(52.0, moderate_pressure + 1.5)
        else:
            bid = 34.0 if high_pressure >= 90 else 42.0
        return float(min(budget, bid))

    if scarcity <= 26:
        if high_pressure >= 120:
            bid = 50.0 if hp >= 7 else 82.0
        elif high_pressure >= 90:
            bid = max(60.0, moderate_pressure + 2.0)
        else:
            bid = 68.0
        return float(min(budget, bid))

    if high_pressure >= 120:
        bid = 62.0 if hp >= 8 else 95.0
    elif high_pressure >= 90:
        bid = 78.0
    else:
        bid = 84.0

    if day >= 8 and hp >= 6 and budget < 140:
        bid -= 10.0

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('day') == current_day - 1 and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    base_bid = DAILY_SALARY * 0.85

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            if my_hp <= 3 or my_no_water_days >= 1:
                base_bid = highest_prev_bid + 5
            else:
                base_bid = max(base_bid, highest_prev_bid + 1)
        else:
            if my_hp <= 3 or my_no_water_days >= 1:
                base_bid = max(base_bid, highest_prev_bid + 10)
            else:
                base_bid = max(base_bid, DAILY_SALARY * 0.75)

    if my_hp <= 1:
        base_bid = my_budget
    elif my_hp <= 3 or my_no_water_days >= 1:
        base_bid = max(base_bid, DAILY_SALARY * 0.95)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 1 and my_hp <= 5:
        base_bid = my_budget
    elif remaining_days <= 2 and my_hp <= 3:
        base_bid = max(base_bid, my_budget * 0.8)

    final_bid = min(my_budget, base_bid)

    return max(1.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    max_prev = max(yesterday_bids) if yesterday_bids else 0
    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev + 5.0)
    if supply < 18:
        return min(my_status['budget'], max(DAILY_SALARY * 0.7, max_prev + 1.0))
    return min(my_status['budget'], max(DAILY_SALARY * 0.4, max_prev * 0.8))
